const crypto = require('crypto');
const today = new Date().toISOString().slice(0, 10);
const timestamp = String(Date.now());
const path = `/api/n8n/overdue?date=${today}`;
// Unique per run; HTTP retries reuse it, and Convex claims it only after a successful read.
const eventId = `overdue-fetch:${today}:${crypto.randomUUID()}`;
const signature = crypto.createHmac('sha256', $env.N8N_SHARED_SECRET).update(`${timestamp}.GET.${path}.`).digest('hex');
return [{ json: { today, path, url: `${$env.CONVEX_HTTP_URL}${path}`, timestamp, eventId, signature } }];

const crypto = require('crypto');
const hmac = (message) => crypto.createHmac('sha256', $env.N8N_SHARED_SECRET).update(message).digest('hex');
const safeEqual = (signature, expected) => {
  if (!/^[a-f0-9]{64}$/i.test(String(signature))) return false;
  return crypto.timingSafeEqual(Buffer.from(String(signature), 'hex'), Buffer.from(expected, 'hex'));
};

// $json is the full HTTP response; with the "text" response format n8n keeps the raw body in `data`.
const signed = $('Sign overdue request').first().json;
const headers = $json.headers || {};
if (String(headers['x-lendloop-timestamp'] || '') !== signed.timestamp) throw new Error('Convex response timestamp mismatch');
if (typeof $json.data !== 'string') throw new Error('Expected the raw Convex response body as text');
const rawBody = $json.data;
const expected = hmac(`${signed.timestamp}.${$json.statusCode}.${signed.path}.${rawBody}`);
if (!safeEqual(headers['x-lendloop-signature'], expected)) throw new Error('Invalid Convex response signature');

const { items } = JSON.parse(rawBody);
if (!Array.isArray(items)) throw new Error('Convex response has no items array');
return [{ json: { items } }];

// Runs once per overdue loan, so every borrower gets their own reminder.
const e = $json;
return { json: { ...e, mail: {
  From: { Email: 'reminders@lendloop.local', Name: 'LendLoop' },
  To: [{ Email: e.recipientEmail, Name: e.recipientName }],
  Subject: `Reminder: ${e.toolName} is overdue`,
  Text: `Hi ${e.recipientName}, ${e.toolName} was due back on ${e.dueDate}. Please arrange its return with your neighbor.`,
} } };

// Error branch of the send step: the failure is written back to Convex instead of being dropped.
const { mail, ...reminder } = $('Prepare reminder').item.json;
const error = String($json.error?.message || $json.error || 'Reminder delivery failed').slice(0, 300);
return { json: { ...reminder, status: 'failed', error } };

const crypto = require('crypto');
const reminderDate = new Date().toISOString().slice(0, 10);
const payload = { idempotencyKey: $json.idempotencyKey, loanId: $json.loanId, reminderDate, status: $json.status };
if ($json.error) payload.error = $json.error;
const body = JSON.stringify(payload);
const timestamp = String(Date.now());
const path = '/api/n8n/reminders';
// New ID per write-back; HTTP retries reuse it so Convex acknowledges them as duplicates.
// The reminder itself is upserted on idempotencyKey (loan + date), so reruns never duplicate it.
const eventId = `${$json.idempotencyKey}:${$json.status}:${crypto.randomUUID()}`;
const signature = crypto.createHmac('sha256', $env.N8N_SHARED_SECRET).update(`${timestamp}.POST.${path}.${body}`).digest('hex');
return { json: { url: `${$env.CONVEX_HTTP_URL}${path}`, path, timestamp, eventId, signature, body, loanId: $json.loanId, status: $json.status } };

const crypto = require('crypto');
const hmac = (message) => crypto.createHmac('sha256', $env.N8N_SHARED_SECRET).update(message).digest('hex');
const safeEqual = (signature, expected) => {
  if (!/^[a-f0-9]{64}$/i.test(String(signature))) return false;
  return crypto.timingSafeEqual(Buffer.from(String(signature), 'hex'), Buffer.from(expected, 'hex'));
};

// $json is the full HTTP response; with the "text" response format n8n keeps the raw body in `data`.
const signed = $('Sign reminder write-back').item.json;
const headers = $json.headers || {};
if (String(headers['x-lendloop-timestamp'] || '') !== signed.timestamp) throw new Error('Convex response timestamp mismatch');
if (typeof $json.data !== 'string') throw new Error('Expected the raw Convex response body as text');
const rawBody = $json.data;
const expected = hmac(`${signed.timestamp}.${$json.statusCode}.${signed.path}.${rawBody}`);
if (!safeEqual(headers['x-lendloop-signature'], expected)) throw new Error('Invalid Convex response signature');

return { json: { loanId: signed.loanId, status: signed.status, acknowledgement: JSON.parse(rawBody) } };

// Every write-back has completed by now. If any send failed, fail this execution so the
// error workflow alerts an operator; the failed reminders are retried on the next run.
const failed = $input.all().filter((item) => item.json.status === 'failed');
if (failed.length) {
  throw new Error(`${failed.length} overdue reminder(s) failed to send and were recorded as failed in Convex`);
}
return $input.all();
